class Solution {
    int find(int x, vector<int>& parent, vector<double>& weight) {
        if (parent[x] != x) {
            int orig_parent = parent[x];
            parent[x] = find(orig_parent, parent, weight);
            weight[x] *= weight[orig_parent];
        }
        return parent[x];
    }

public:
    vector<double> calcEquation(vector<vector<string>>& equations, vector<double>& values, vector<vector<string>>& queries) {
        unordered_map<string, int> varToId;
        int id = 0;
        for (const auto& eq : equations) {
            if (!varToId.count(eq[0])) varToId[eq[0]] = id++;
            if (!varToId.count(eq[1])) varToId[eq[1]] = id++;
        }

        vector<int> parent(id);
        vector<double> weight(id);
        for (int i = 0; i < id; ++i) {
            parent[i] = i;
            weight[i] = 1.0;
        }

        for (int i = 0; i < equations.size(); ++i) {
            int u = varToId[equations[i][0]];
            int v = varToId[equations[i][1]];
            double val = values[i];

            int rootU = find(u, parent, weight);
            int rootV = find(v, parent, weight);

            if (rootU != rootV) {
                parent[rootU] = rootV;
                weight[rootU] = weight[v] * val / weight[u];
            }
        }

        vector<double> ans;
        for (const auto& q : queries) {
            if (!varToId.count(q[0]) || !varToId.count(q[1])) {
                ans.push_back(-1.0);
                continue;
            }
            int u = varToId[q[0]];
            int v = varToId[q[1]];
            int rootU = find(u, parent, weight);
            int rootV = find(v, parent, weight);
            if (rootU != rootV) {
                ans.push_back(-1.0);
            } else {
                ans.push_back(weight[u] / weight[v]);
            }
        }
        return ans;
    }
};
